{"content":""""Vercel Python entrypoint for MusicAI.

This keeps the public app lightweight while exposing the OAuth/account hub used
for the modern multi-provider MusicAI experience.
"""

from pathlib import Path
import os
import sys
import time
from urllib.parse import urlencode

import requests
from flask import Flask, jsonify, redirect, render_template, request, session

PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from providers import get_music_providers
from provider_oauth import complete_provider_oauth, start_provider_oauth
from token_store import ProviderToken, list_provider_tokens, save_provider_token

app = Flask(
    __name__,
    static_url_path="/static",
    static_folder=str(PROJECT_ROOT / "static"),
    template_folder=str(PROJECT_ROOT / "templates"),
)
app.secret_key = os.getenv("FLASK_SECRET_KEY", "musicai-preview")

SPOTIFY_SCOPES = " ".join(
    [
        "user-read-recently-played",
        "user-top-read",
        "playlist-read-private",
        "playlist-read-collaborative",
        "user-library-read",
        "user-read-email",
        "user-read-private",
    ]
)


def spotify_login_url() -> str:
    client_id = os.getenv("SPOTIFY_CLIENT_ID", "")
    redirect_uri = os.getenv("SPOTIFY_CALLBACK_URL", "https://musicai-rouge.vercel.app/login/")
    if not client_id:
        return "#providers"
    return "https://accounts.spotify.com/authorize?" + urlencode(
        {
            "client_id": client_id,
            "response_type": "code",
            "redirect_uri": redirect_uri,
            "scope": SPOTIFY_SCOPES,
            "show_dialog": "true",
        }
    )


def _fetch_spotify_profile(access_token: str | None) -> dict:
    if not access_token:
        return {}
    response = requests.get(
        "https://api.spotify.com/v1/me",
        headers={"Authorization": f"Bearer {access_token}"},
        timeout=20,
    )
    if response.status_code >= 400:
        return {}
    return response.json()


def _exchange_spotify_code(code: str) -> ProviderToken:
    client_id = os.getenv("SPOTIFY_CLIENT_ID", "")
    client_secret = os.getenv("SPOTIFY_CLIENT_SECRET", "")
    redirect_uri = os.getenv("SPOTIFY_CALLBACK_URL", "https://musicai-rouge.vercel.app/login/")
    if not client_id or not client_secret:
        raise RuntimeError("Spotify OAuth credentials are not configured")

    response = requests.post(
        "https://accounts.spotify.com/api/token",
        data={
            "grant_type": "authorization_code",
            "code": code,
            "redirect_uri": redirect_uri,
            "client_id": client_id,
            "client_secret": client_secret,
        },
        timeout=20,
    )
    response.raise_for_status()
    payload = response.json()
    profile = _fetch_spotify_profile(payload.get("access_token"))
    account_id = profile.get("id") or profile.get("email") or "spotify-user"
    user_id = session.get("user_id") or profile.get("email") or f"spotify:{account_id}"

    token = ProviderToken(
        user_id=user_id,
        provider="spotify",
        provider_account_id=account_id,
        access_token=payload.get("access_token"),
        refresh_token=payload.get("refresh_token"),
        expires_at=time.time() + payload.get("expires_in", 3600),
        scopes=payload.get("scope") or SPOTIFY_SCOPES,
        metadata={
            "email": profile.get("email"),
            "name": profile.get("display_name"),
            "country": profile.get("country"),
            "product": profile.get("product"),
        },
    )
    save_provider_token(token)
    session["user_id"] = user_id
    session["email"] = profile.get("email") or session.get("email")
    session["spotify_connected"] = True
    return token


def _current_connections() -> list[dict]:
    user_id = session.get("user_id")
    if not user_id:
        return []
    try:
        return list_provider_tokens(user_id)
    except Exception:
        return []


@app.route("/healthz", methods=["GET"])
def healthz():
    return jsonify(
        {
            "ok": True,
            "app": "MusicAI",
            "providers": {
                "spotify": bool(os.getenv("SPOTIFY_CLIENT_ID") and os.getenv("SPOTIFY_CLIENT_SECRET")),
                "genius": bool(os.getenv("GENIUS_API_KEY")),
                "watson": bool(os.getenv("WATSON_API_KEY") and os.getenv("WATSON_SERVICE_URL")),
                "google_youtube": bool(os.getenv("GOOGLE_CLIENT_ID") and os.getenv("GOOGLE_CLIENT_SECRET")),
                "apple_music": bool(os.getenv("APPLE_TEAM_ID") and os.getenv("APPLE_KEY_ID") and os.getenv("APPLE_PRIVATE_KEY")),
                "soundcloud": bool(os.getenv("SOUNDCLOUD_CLIENT_ID") and os.getenv("SOUNDCLOUD_CLIENT_SECRET")),
            },
        }
    )


@app.route("/", methods=["GET"])
def home():
    return dashboard()


@app.route("/login/", methods=["GET"])
def spotify_callback():
    if "error" in request.args:
        return jsonify({"ok": False, "provider": "spotify", "error": request.args.get("error")}), 400
    code = request.args.get("code")
    if not code:
        return redirect(spotify_login_url())
    try:
        _exchange_spotify_code(code)
        return redirect("/Dashboard")
    except Exception as exc:
        return jsonify({"ok": False, "provider": "spotify", "error": str(exc)}), 400


@app.route("/providers/<provider_id>/connect", methods=["GET"])
def provider_connect(provider_id):
    try:
        start = start_provider_oauth(provider_id)
        if start.state:
            session[f"{provider_id}_oauth_state"] = start.state
        if start.token:
            session[f"{provider_id}_oauth_token"] = start.token
        return redirect(start.url)
    except Exception as exc:
        return jsonify({"ok": False, "provider": provider_id, "error": str(exc)}), 400


@app.route("/providers/<provider_id>/callback", methods=["GET"])
def provider_callback(provider_id):
    try:
        if provider_id in {"youtube_music", "soundcloud"}:
            expected_state = session.get(f"{provider_id}_oauth_state")
            returned_state = request.args.get("state")
            if expected_state and returned_state != expected_state:
                raise RuntimeError("OAuth state mismatch")
        user_id = session.get("user_id") or session.get("email") or request.remote_addr or "vercel-user"
        token = complete_provider_oauth(provider_id, request.args.to_dict(), user_id)
        session["user_id"] = user_id
        session[f"{provider_id}_connected"] = True
        if token.metadata and token.metadata.get("email"):
            session["email"] = token.metadata.get("email")
        return redirect("/Dashboard")
    except Exception as exc:
        return jsonify({"ok": False, "provider": provider_id, "error": str(exc)}), 400


@app.route("/Dashboard", methods=["GET"])
def dashboard():
    login_url = spotify_login_url()
    connected = _current_connections()
    connected_ids = {item["provider"] for item in connected}
    providers = get_music_providers(login_url)
    user_label = session.get("email") or session.get("user_id") or "New MusicAI listener"
    connected_names = ", ".join(
        provider["name"] for provider in providers if provider["id"] in connected_ids
    )
    return render_template(
        "provider_dashboard.html",
        providers=providers,
        connected=connected,
        connected_ids=connected_ids,
        connected_names=connected_names,
        user_label=user_label,
    )


application = app
"}

